def _numfmt(x, sep, dec, neg):
    s = "%.*f" % (dec, abs(float(x)))
    ip, _, fp = s.partition(".")
    g = []
    while len(ip) > 3:
        g.insert(0, ip[-3:])
        ip = ip[:-3]
    g.insert(0, ip)
    body = sep.join(g) + ("." + fp if dec else "")
    if float(x) < 0:
        return ("(" + body + ")") if neg == "paren" else ("-" + body)
    return body
